public class PayrollBonus {String id;double salary;PayrollBonus(String id,double salary){this.id=id;this.salary=salary;}void raiseSalary(double salary){this.salary+=salary;}public static void main(String[]x){double[]s={40000,55000,62000,48000};for(int i=0;i<s.length;i++){PayrollBonus e=new PayrollBonus("E-10"+(i+1),s[i]);e.raiseSalary(5000);System.out.println(e.id+" | Final Salary: Rs "+e.salary);}}}
